"""Retailer education, not an automated audit, quote or service activation."""
from html import escape

CHECKLIST_PATH = '/guides/flooring-marketing-checklist/'
REVIEW_PATH = '/guides/your-first-marketing-review/'
CHECKS = [
    ('inquiry', 'Can a homeowner take the next step?',
     'Open your homepage and one important flooring or installation page on your phone. Can you find the location, the help you offer and a clear way to ask about an estimate? Check the destination shown by phone, email and form links without sending a test inquiry.',
     'Write down the page and the point where a shopper could get stuck. Agree a controlled delivery test with the receiving team before treating a form as verified.',
     '/services/websites/', 'Website and inquiry path'),
    ('local', 'Do your local business details agree?',
     'Compare your public Business Profile with your website: real business name, address, phone, regular and special hours, and the area you actually serve. Note missing or conflicting facts. One search on your own phone does not establish your local ranking.',
     'Confirm the correct details with your team, then identify who has permission to make each correction.',
     '/services/local-seo/', 'Local business information'),
    ('answers', 'Do your pages answer real flooring questions?',
     'Choose a product or installation service you actually offer. Look for a useful page explaining it, where it is available and how to get help. Use accurate descriptions and real photos you have permission to use. List questions the page leaves unanswered.',
     'Choose one important unanswered shopper question and the existing page that should address it before planning more pages.',
     '/services/ai-search/', 'Useful pages for search and AI'),
    ('advertising', 'Does an ad lead to the right page?',
     'If you run ads, inspect the saved ad and its destination through an account you are authorized to use. Does the product, offer, location and next step agree with the landing page? Check the intended area and approved budget. Do not click your live ads to test them.',
     'Record the specific mismatch and ask the account owner to review it. Keep management fees, platform media and optional tools separate when comparing costs.',
     '/services/paid-ads/', 'Advertising and landing pages'),
    ('measurement', 'Do the numbers describe useful inquiries?',
     'Ask which actions count as a conversion: a form, a call, a directions click or a purchase. Review definitions and date ranges before comparing totals. Ask who answers new inquiries and how you learn whether they became estimates or sold jobs. Use summaries, not customer records, for an initial conversation.',
     'Agree one useful inquiry definition, a responsible person and a review period. Record missing tracking rather than counting every platform conversion as a sale.',
     '/services/paid-ads/', 'Measurement and response'),
    ('access', 'Do you know what can stay and what can move?',
     'List your domain, website, business email, Business Profile, ad accounts, catalogs and other licensed tools. Note the owner or administrator and what you do not yet know. Review the current agreement privately for notice, renewal and access or export limits. A new website is not automatically necessary.',
     'Confirm access, rights and dependencies before choosing a replacement or cancellation date. Keep business email and inquiry destinations in the transition plan.',
     REVIEW_PATH + '#transition', 'Current website and provider access'),
]


def resource_links():
    return f'<aside class="retailer-links"><b>Start with your own showroom</b><p><a href="{CHECKLIST_PATH}">Use the flooring marketing checklist</a> to note what works and what needs checking. Then <a href="{REVIEW_PATH}">prepare for your first marketing review</a>.</p></aside>'


def checklist_body():
    sections = []
    for index, (key, question, check, action, href, label) in enumerate(CHECKS, 1):
        sections.append(f'''<section class="diagnostic-check" id="check-{key}" data-diagnostic-check>
<h2>{index}. {question}</h2><p>{check}</p>
<details><summary>What to do with what you find</summary><p data-check-action>{action}</p><p><a data-check-link href="{href}">{label}</a></p></details>
<div class="field"><label for="answer-{key}">Your observation: {question}</label>
<select id="answer-{key}" data-check-answer data-check-title="{escape(label, quote=True)}">
<option value="unknown">Not checked / not sure</option><option value="review">Needs a closer look</option><option value="checked">Checked and looks okay</option><option value="na">Not applicable right now</option></select></div></section>''')
    return f'''<section class="section"><div class="wrap article-layout" data-diagnostic>
<p class="answer">Use this flooring marketing checklist to turn a broad concern into specific questions about your website, local visibility and advertising. Your observations help start a conversation; this page does not scan your site or calculate a marketing score.</p>
<div class="callout"><h2>Start with what you can see</h2><p>Use this with your own team, current provider or CDL. No login or email is needed. Review public pages and accounts you already have permission to use. Mark unknown items honestly. Avoid changing live settings or submitting real inquiries during this first look.</p><p>Your choices are used only on this page. This checklist does not send or store them. Use your browser’s print option to keep a copy; they are not attached to a contact request.</p><a href="#check-inquiry">Begin the six checks ↓</a></div>
{''.join(sections)}
<div class="diagnostic-tools" hidden data-diagnostic-tools><button class="btn" type="button" data-build-review>Show my discussion points</button><button class="diagnostic-secondary" type="button" data-clear-review>Reset choices</button></div>
<noscript><p class="callout">The checklist and guidance work without JavaScript. Note your answers privately, choose the question that matters most and use the review guide below.</p></noscript>
<section class="diagnostic-summary" hidden data-diagnostic-summary aria-labelledby="discussion-title"><h2 id="discussion-title" tabindex="-1">Your discussion points</h2><p data-summary-intro></p><ul data-summary-list></ul><p data-summary-unknown></p><p>These are your observations. A person still needs to review the evidence and any access limits before recommending work.</p><button class="diagnostic-secondary" type="button" data-print-review>Print or save with your browser</button></section>
<section id="next-step"><h2>Choose a useful next conversation</h2><p>Start with an obstacle that prevents a shopper from asking for help. Then choose the local-search or advertising question most relevant to your store. A useful existing site may only need specific improvements.</p><p><a class="btn" href="{REVIEW_PATH}">Prepare for my first review <span aria-hidden="true">→</span></a></p><p>Already spoken with CDL? <a href="/contact/#after-call">Continue the conversation</a>. Share only the points you choose; this checklist does not send them automatically. You can also <a href="/contact/">request the free three-priority review</a>.</p></section>
<section class="resource-sources"><h2>Why these checks matter</h2><p>Google recommends accurate, complete business information for local discovery and helpful, accessible pages for search. Its usual SEO guidance also applies to AI features. Inclusion or ranking is never assured.</p><ul><li><a href="https://support.google.com/business/answer/7091">Google: improve your local ranking</a></li><li><a href="https://developers.google.com/search/docs/fundamentals/seo-starter-guide">Google: SEO Starter Guide</a></li><li><a href="https://developers.google.com/search/docs/appearance/ai-features">Google: AI features and your website</a></li><li><a href="https://support.google.com/google-ads/answer/11461796">Google Ads: primary and secondary conversion actions</a></li></ul><p class="article-meta">Educational guidance reviewed November 5, 2026. Your account, website and agreement require their own review.</p></section>
</div></section>'''


def first_review_body():
    return f'''<section class="section"><div class="wrap article-layout">
<p class="answer">The first marketing review starts with the showroom you have today: what you sell, where you serve customers, how people ask for help and what you want to improve. The aim is to identify three useful priorities and decide what is worth investigating next.</p>
<nav class="toc" aria-label="On this page"><b>Prepare a useful conversation</b><a href="#bring">What to bring</a><a href="#assessment">The first assessment</a><a href="#services">Which work fits?</a><a href="#transition">Your current website</a><a href="#follow-up">Agree the next step</a></nav>
<section id="bring"><h2>Bring a few facts, not a folder of passwords</h2><ul><li>Your showroom name, location, public website and the products or installation services you want to discuss.</li><li>One specific concern, such as a confusing estimate page, incorrect hours or an ad leading to the wrong product.</li><li>What you know about the current provider, who controls the domain and accounts, and any known renewal or end date. “I need to check” is a useful answer.</li><li>If available, a summary of recent inquiries and ad spend for the same date range, with an explanation of what each number counts. A report is optional for the first conversation.</li></ul><p>Keep customer records, account credentials and full agreements out of the public inquiry form. If an account-level review is needed later, agree the purpose and limited access with the account owner. Use access invitations rather than sharing passwords.</p><p><a href="{CHECKLIST_PATH}">Use the six-check worksheet</a> to organize observations. Its answers stay on that page and are not sent to CDL.</p></section>
<section id="assessment"><h2>What the first assessment can establish</h2><ol><li><strong>Understand the showroom.</strong> Confirm the work you actually offer, service area, current site and the problem you want solved.</li><li><strong>Review what is visible.</strong> Look at public pages, local information and the route to an inquiry. Record specific observations and anything that needs account access or a controlled test.</li><li><strong>Discuss three priorities.</strong> Separate an observed issue from a hypothesis. Decide what can be improved on the current setup and what needs investigation before a proposal.</li></ol><p>A public-page review cannot establish every account setting, form destination, sales result or contractual right. We identify those limits. Asking for a review starts no paid service or switching credit.</p></section>
<section id="services"><h2>Match the work to the problem</h2><div class="resource-options"><article><h3>A clearer website</h3><p>For confusing product pages, missing local details or a difficult inquiry path. Assess improvements to the existing site before deciding on a replacement.</p><a href="/services/websites/">Review website scope</a></article><article><h3>Local SEO and useful answers</h3><p>For inconsistent business information or missing pages about services you really offer. Clear facts and useful answers also support AI-search eligibility; they cannot guarantee a recommendation.</p><a href="/services/local-seo/">Review local SEO</a> · <a href="/services/ai-search/">Understand AI search work</a></article><article><h3>Advertising with a clear destination</h3><p>For a defined product, market and budget. Review the ad, landing page, inquiry definition and response process together. Management fees and platform media are separate.</p><a href="/services/paid-ads/">Review advertising scope</a></article></div><p>Keep your existing CRM and showroom systems in the discussion. CRM integration is planned for later and is not part of the current marketing offer. Pricing and transition details remain <a href="/pricing/">proposed for review</a>.</p></section>
<section id="transition"><h2>Plan around the website you already have</h2><p>You do not need to cancel your current provider to start a conversation. Where access, compatibility and the inquiry path support the agreed work, SEO or advertising can use your existing website.</p><ol><li><strong>Map what must keep working.</strong> List the domain, business email, phone routing, forms, important page URLs, Business Profile, ad accounts, catalogs and licensed tools. Confirm each owner, access limit and relevant agreement.</li><li><strong>Agree the actual change.</strong> Decide what stays, what changes, who approves it and who makes the cutover. Review rights, notice and any proposed CDL credits separately. Do not assume a catalog, design or license can transfer.</li><li><strong>Prepare and verify.</strong> Keep useful URLs when possible. If URLs must change, prepare old-to-new mappings and appropriate redirects. Check the candidate pages on mobile and desktop, and arrange controlled inquiry-delivery checks with the receiving team.</li><li><strong>Switch deliberately, then monitor.</strong> Confirm backups, recovery steps, ownership and a suitable change window before DNS or other live changes. Monitor important pages and inquiry routes afterward. Keep the old service until the agreed transition and existing obligations are handled.</li></ol><p>A domain or URL change is different from changing hosting while keeping the same URLs. Search visibility can fluctuate during a move. The plan should fit the actual change, not assume a redesign will protect or improve every ranking.</p><p><a href="/guides/switching-flooring-website-providers/">Work through the switch-readiness checklist</a> for evidence, unknowns and the cutover plan.</p><p><a href="/switch/">Review the proposed switching support and open terms</a>. Credits concern CDL website-service fees; they do not pay your old provider or cancel its agreement.</p></section>
<section id="follow-up"><h2>Leave with one clear next step</h2><p>Write down the observation, the evidence still needed, the responsible person and the next review point. A useful outcome may be a specific correction, an access check, an itemized proposal or a decision to keep things as they are. You can decide whether to proceed after reviewing it.</p><p>Before paid work, agree scope, responsibilities, separate fees/media/tools, timing, account control and any notice or transition terms in writing. No ranking, AI mention, lead count or sales result is promised.</p><p><a class="btn" href="/contact/#after-call">Continue our conversation <span aria-hidden="true">→</span></a></p><p>New to CDL? <a href="/contact/">Request a free growth audit</a> or <a href="/about/">read about our showroom background</a>.</p></section>
<section class="resource-sources"><h2>Further reading</h2><ul><li><a href="https://developers.google.com/search/docs/crawling-indexing/site-move-with-url-changes">Google: planning a site move with URL changes</a></li><li><a href="https://support.google.com/google-ads/answer/9978556">Google Ads: account access levels</a></li><li><a href="https://developers.google.com/search/docs/appearance/ai-features">Google: AI features and your website</a></li></ul><p class="article-meta">Educational guidance reviewed November 5, 2026. Confirm your actual accounts, access and provider agreement before making changes.</p></section>
</div></section>'''
